func decodeString(_ s: String) -> String {
    var stack: [(String, Int)] = []
    var current = "", k = 0
    for c in s {
        if let d = c.wholeNumberValue { k = k * 10 + d }
        else if c == "[" { stack.append((current, k)); current = ""; k = 0 }
        else if c == "]" {
            let (prev, n) = stack.removeLast()
            current = prev + String(repeating: current, count: n)
        } else { current.append(c) }
    }
    return current
}
